const { USER_RULES, MESSAGE_RULES, assertRules } = require('./validation');
const { createRateLimiter, createThrottlePolicy } = require('./throttling');
const { formatBase } = require('./formatting');

/**
 * Everything that makes one channel different from another. Definitions are
 * plain data plus pure functions; `composeNotifier` supplies the shared behavior.
 *
 * @typedef {object} ChannelDefinition
 * @property {string} name  Channel id. Also the transport method name and the
 *   prefix of payload ids and throttle keys.
 * @property {string} transportLabel  Channel wording in the "transport is not
 *   configured" error.
 * @property {Record<string, unknown>} defaults  Channel settings, including
 *   `maxPerHour`. A truthy factory option with the same name overrides each one.
 * @property {import('./validation').ValidationRule[]} userRules  Checked after
 *   the shared user rules.
 * @property {Array<(user: object, message: object, options: object) => boolean>} throttleExemptions
 *   Any match skips throttling entirely, consent rules included.
 * @property {import('./throttling').ConsentRule[]} consentRules
 * @property {(base: object, context: {user: object, message: object, options: object,
 *   settings: Record<string, unknown>, now: () => Date}) => object} payloadFields
 *   Returns the channel's payload fields, which are merged over the base payload.
 */

function resolveSettings(defaults, factoryOptions) {
  return Object.fromEntries(
    Object.entries(defaults).map(([key, fallback]) => [key, factoryOptions[key] || fallback])
  );
}

/**
 * Builds a notifier by combining a channel definition with the shared
 * validation, throttling, formatting and delivery services.
 *
 * The returned object is frozen. `send` calls the stage functions it closes
 * over, so replacing a stage on the object could not change how `send` behaves.
 *
 * @param {ChannelDefinition} definition
 * @param {object} factoryOptions  Options passed to `createNotifier`.
 */
function composeNotifier(definition, factoryOptions) {
  const channel = definition.name;
  const transport = factoryOptions.transport || {};
  const now = factoryOptions.now || (() => new Date());
  const defaultLocale = factoryOptions.defaultLocale || 'en-US';
  const settings = resolveSettings(definition.defaults, factoryOptions);
  const userRules = [...USER_RULES, ...definition.userRules];
  const rateLimiter = createRateLimiter({
    channel,
    store: factoryOptions.throttleStore || new Map(),
    now,
    maxPerHour: settings.maxPerHour
  });
  const shouldThrottle = createThrottlePolicy({
    exemptions: definition.throttleExemptions,
    rateLimiter,
    consentRules: definition.consentRules
  });

  function validateUser(user) {
    assertRules(userRules, user);
  }

  function validateMessage(message) {
    assertRules(MESSAGE_RULES, message);
  }

  function format(user, message, options = {}) {
    const base = formatBase({ channel, user, message, options, defaultLocale, now });
    return { ...base, ...definition.payloadFields(base, { user, message, options, settings, now }) };
  }

  async function deliver(payload) {
    if (typeof transport[channel] !== 'function') {
      throw new Error(`${definition.transportLabel} transport is not configured`);
    }
    // Invoked as a method so transports that use `this` keep working.
    await transport[channel](payload);
  }

  function recordDelivery(user, message) {
    rateLimiter.record(user, message);
  }

  async function send(user, message, options = {}) {
    validateUser(user);
    validateMessage(message);

    const throttle = shouldThrottle(user, message, options);
    if (throttle.throttled) {
      return {
        channel,
        status: 'throttled',
        reason: throttle.reason,
        retryAt: throttle.retryAt,
        userId: user.id
      };
    }

    const payload = format(user, message, options);
    await deliver(payload);
    recordDelivery(user, message);

    return {
      channel,
      status: 'sent',
      userId: user.id,
      id: payload.id,
      preview: payload.preview
    };
  }

  return Object.freeze({
    channel,
    send,
    validateUser,
    validateMessage,
    shouldThrottle,
    format,
    deliver,
    recordDelivery
  });
}

module.exports = {
  composeNotifier
};
/** Maximum length of the shared `preview`; Slack reuses it for its own preview. */
const PREVIEW_LENGTH = 120;

/** Fills the {{name}}, {{id}} and {{category}} placeholders in a message field. */
function applyTemplate(value, user, message) {
  return String(value)
    .replace(/\{\{name\}\}/g, user.name || 'there')
    .replace(/\{\{id\}\}/g, user.id)
    .replace(/\{\{category\}\}/g, message.category || 'general');
}

/**
 * Builds the channel-independent payload fields. The clock is read twice, for
 * `id` and then `generatedAt`, so a stepping clock gives them different times.
 */
function formatBase({ channel, user, message, options, defaultLocale, now }) {
  const id = `${channel}-${user.id}-${now().getTime()}`;
  const locale = options.locale || user.locale || defaultLocale;
  const title = applyTemplate(message.title, user, message);
  const body = applyTemplate(message.body, user, message);

  return {
    id,
    channel,
    locale,
    title,
    body,
    preview: `${title}: ${body}`.slice(0, PREVIEW_LENGTH),
    metadata: {
      category: message.category || 'general',
      priority: message.priority || 'normal',
      generatedAt: now().toISOString()
    }
  };
}

module.exports = {
  PREVIEW_LENGTH,
  formatBase
};
const { composeNotifier } = require('./composeNotifier');
const email = require('./channels/email');
const sms = require('./channels/sms');
const slack = require('./channels/slack');
const inApp = require('./channels/inapp');

// Returns a plain function, not an arrow, so `new registry.email(options)`
// (valid when registry values were classes) still returns the notifier.
function notifierFactory(definition) {
  return function createChannelNotifier(options = {}) {
    return composeNotifier(definition, options);
  };
}

/** Channel id to notifier factory. `createNotifier` looks channels up here. */
const registry = {
  email: notifierFactory(email),
  sms: notifierFactory(sms),
  slack: notifierFactory(slack),
  inapp: notifierFactory(inApp)
};

/**
 * Creates a notifier for one registered channel.
 * @param {string} channel  A key of `registry`.
 * @param {object} [options]  Shared options (transport, throttleStore, now,
 *   defaultLocale, maxPerHour) plus the channel's own settings.
 * @throws {TypeError} When `channel` is not a registered channel.
 */
function createNotifier(channel, options = {}) {
  // Own keys only: inherited names such as "constructor" are not channels.
  const factory = Object.hasOwn(registry, channel) ? registry[channel] : undefined;
  if (typeof factory !== 'function') {
    throw new TypeError(`unknown notification channel: ${channel}`);
  }
  return factory(options);
}

/** Creates one notifier per registered channel, keyed by channel id, from the same options. */
function createAllNotifiers(options = {}) {
  return Object.keys(registry).reduce((all, channel) => {
    all[channel] = createNotifier(channel, options);
    return all;
  }, {});
}

module.exports = {
  createNotifier,
  createAllNotifiers,
  registry
};
/**
 * @typedef {object} ValidationRule
 * @property {(value: any) => boolean} check  Returns true when the value is acceptable.
 * @property {string} error  Message of the TypeError thrown when `check` fails.
 */

/**
 * Recipient rules every channel applies before its own `userRules`.
 * @type {ValidationRule[]}
 */
const USER_RULES = [
  { check: user => Boolean(user) && typeof user === 'object', error: 'user is required' },
  { check: user => Boolean(user.id), error: 'user.id is required' }
];

/** @type {ValidationRule[]} */
const MESSAGE_RULES = [
  { check: message => Boolean(message) && typeof message === 'object', error: 'message is required' },
  {
    check: message => Boolean(message.title && message.body),
    error: 'message.title and message.body are required'
  }
];

/**
 * Throws a TypeError for the first rule `value` fails. Rules run in order and
 * stop at the first failure, so a rule may rely on the ones before it.
 * @param {ValidationRule[]} rules
 * @param {unknown} value
 */
function assertRules(rules, value) {
  const failed = rules.find(rule => !rule.check(value));
  if (failed) {
    throw new TypeError(failed.error);
  }
}

module.exports = {
  USER_RULES,
  MESSAGE_RULES,
  assertRules
};
const { requireMarketingOptIn } = require('../throttling');

const EMAIL_PREVIEW_LENGTH = 90;

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function footerFor(user, message, unsubscribeBaseUrl) {
  if (message.category === 'transactional' || message.category === 'security') {
    return `Sent to ${user.email} because of recent account activity.`;
  }
  const url = `${unsubscribeBaseUrl}?user=${encodeURIComponent(user.id)}`;
  return `You can unsubscribe at ${url}.`;
}

/** @type {import('../composeNotifier').ChannelDefinition} */
module.exports = {
  name: 'email',
  transportLabel: 'email',
  defaults: {
    maxPerHour: 8,
    from: 'noreply@example.com',
    replyTo: 'support@example.com',
    unsubscribeBaseUrl: 'https://example.com/unsubscribe'
  },
  userRules: [
    {
      check: user => Boolean(user.email) && user.email.includes('@'),
      error: 'user.email is required for email notifications'
    }
  ],
  throttleExemptions: [],
  consentRules: [requireMarketingOptIn('emailOptIn', 'email')],
  payloadFields(base, { user, message, settings }) {
    const subjectPrefix = message.category === 'security' ? '[Action Required] ' : '';
    const footer = footerFor(user, message, settings.unsubscribeBaseUrl);

    return {
      to: user.email,
      from: settings.from,
      replyTo: settings.replyTo,
      subject: `${subjectPrefix}${base.title}`,
      text: `${base.body}\n\n${footer}`,
      html: `<h1>${escapeHtml(base.title)}</h1><p>${escapeHtml(base.body)}</p><footer>${escapeHtml(footer)}</footer>`,
      preview: base.body.slice(0, EMAIL_PREVIEW_LENGTH)
    };
  }
};
const URGENT_EXPIRY_HOURS = 72;
const DEFAULT_EXPIRY_HOURS = 168;

/** @type {import('../composeNotifier').ChannelDefinition} */
module.exports = {
  name: 'inapp',
  transportLabel: 'in-app',
  defaults: {
    maxPerHour: 50,
    defaultIcon: 'bell',
    defaultAction: '/notifications'
  },
  userRules: [
    {
      check: user => !user.disabledInApp,
      error: 'in-app notifications are disabled for this user'
    }
  ],
  throttleExemptions: [(user, message) => message.category === 'security'],
  consentRules: [],
  payloadFields(base, { user, message, options, settings, now }) {
    const expiresInHours =
      options.expiresInHours || (message.priority === 'urgent' ? URGENT_EXPIRY_HOURS : DEFAULT_EXPIRY_HOURS);
    // Multiplied left to right on purpose: a precomputed ms-per-hour constant
    // rounds differently for fractional hours.
    const expiresAt = new Date(now().getTime() + expiresInHours * 60 * 60 * 1000);

    return {
      userId: user.id,
      icon: message.icon || settings.defaultIcon,
      actionUrl: options.actionUrl || message.actionUrl || settings.defaultAction,
      read: false,
      expiresAt: expiresAt.toISOString(),
      preview: base.title
    };
  }
};
const { PREVIEW_LENGTH } = require('../formatting');

function blocksFor(base, mention) {
  return [
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `${mention}*${base.title}*`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: base.body
      }
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `Category: ${base.metadata.category}`
        }
      ]
    }
  ];
}

/** @type {import('../composeNotifier').ChannelDefinition} */
module.exports = {
  name: 'slack',
  transportLabel: 'slack',
  defaults: {
    maxPerHour: 20,
    defaultWorkspace: 'main',
    defaultChannel: '#general'
  },
  userRules: [
    {
      check: user => Boolean(user.slackId || user.slackChannel),
      error: 'user.slackId or user.slackChannel is required for Slack notifications'
    }
  ],
  throttleExemptions: [(user, message, options) => Boolean(options.threadTs)],
  consentRules: [],
  // `channel` here is the Slack channel; it replaces the base payload's channel id.
  payloadFields(base, { user, options, settings }) {
    const mention = user.slackId ? `<@${user.slackId}> ` : '';
    const text = `${mention}*${base.title}*\n${base.body}`;

    return {
      workspace: user.slackWorkspace || settings.defaultWorkspace,
      channel: options.channel || user.slackChannel || settings.defaultChannel,
      threadTs: options.threadTs || null,
      text,
      blocks: blocksFor(base, mention),
      preview: text.replace(/\*/g, '').slice(0, PREVIEW_LENGTH)
    };
  }
};
const { requireMarketingOptIn } = require('../throttling');

const E164_PATTERN = /^\+[1-9]\d{6,14}$/;

function truncate(value, maxLength) {
  if (value.length <= maxLength) {
    return value;
  }
  return `${value.slice(0, maxLength - 1)}…`;
}

/** @type {import('../composeNotifier').ChannelDefinition} */
module.exports = {
  name: 'sms',
  transportLabel: 'sms',
  defaults: {
    maxPerHour: 4,
    senderId: 'APP',
    segmentLength: 140
  },
  userRules: [
    {
      check: user => Boolean(user.phone) && E164_PATTERN.test(user.phone),
      error: 'user.phone must be E.164 for SMS notifications'
    }
  ],
  throttleExemptions: [],
  consentRules: [requireMarketingOptIn('smsOptIn', 'SMS')],
  payloadFields(base, { user, message, settings }) {
    const prefix = message.priority === 'urgent' ? 'URGENT: ' : '';
    const text = truncate(`${prefix}${base.title} - ${base.body}`, settings.segmentLength);

    return {
      to: user.phone,
      from: settings.senderId,
      text,
      segments: Math.ceil(text.length / settings.segmentLength),
      preview: text
    };
  }
};
# Notifications

Sends a notification to one user over `email`, `sms`, `slack` or `inapp`.

## Usage

```js
const { createNotifier, createAllNotifiers } = require('./src/notifications');

const transport = { email: async payload => mailer.send(payload) };
const email = createNotifier('email', { transport, from: 'alerts@example.com' });

const result = await email.send(
  { id: 'u1', name: 'Ava', email: 'ava@example.com' },
  { title: 'Hello {{name}}', body: 'Your report is ready', category: 'transactional' }
);
// { channel: 'email', status: 'sent', userId: 'u1', id: 'email-u1-<ms>', preview: '...' }

const all = createAllNotifiers({ transport }); // { email, sms, slack, inapp }
```

`send` rejects with a `TypeError` when the user or message is invalid. When the
throttle policy blocks a message, `send` resolves to
`{ channel, status: 'throttled', reason, retryAt, userId }` and nothing is delivered.

## Options

Factory options shared by every channel:

| Option | Default | Notes |
| --- | --- | --- |
| `transport` | `{}` | One method per channel id (`email`, `sms`, `slack`, `inapp`), called with the payload. |
| `throttleStore` | a new `Map` per notifier | Anything with Map-style `get`/`set`. Notifiers given the same store share throttle history. |
| `now` | `() => new Date()` | Clock used for ids, timestamps and throttling. |
| `defaultLocale` | `'en-US'` | |
| `maxPerHour` | email 8, sms 4, slack 20, inapp 50 | Per user and message category. |

Channel options: `from`, `replyTo`, `unsubscribeBaseUrl` (email); `senderId`,
`segmentLength` (sms); `defaultWorkspace`, `defaultChannel` (slack);
`defaultIcon`, `defaultAction` (inapp). Any falsy value, including `0` and `''`,
falls back to the default.

Per-send options: `force`, `locale`, `channel` and `threadTs` (Slack),
`actionUrl` and `expiresInHours` (in-app).

## Layout

| File | Responsibility |
| --- | --- |
| `index.js` | Public factory: `createNotifier`, `createAllNotifiers`, `registry`. |
| `composeNotifier.js` | Combines a channel definition with the shared services and runs the send pipeline. |
| `validation.js` | Declarative user and message rules. |
| `throttling.js` | Hourly rate limiter, marketing consent rule, throttle policy. |
| `formatting.js` | Template placeholders and the payload fields every channel shares. |
| `channels/*.js` | One definition per channel. |

## Send pipeline

1. Validate the user: the shared rules (an object with an `id`), then the channel's `userRules`.
2. Validate the message: an object with `title` and `body`.
3. Apply the throttle policy, in this order:
   - Exemptions allow the send outright. Slack thread replies (`threadTs`) and
     in-app `security` messages are exempt.
   - The hourly rate limit. `force: true` or `priority: 'urgent'` skips it.
   - Consent rules. Email and SMS block `marketing` messages unless
     `user.emailOptIn` / `user.smsOptIn` is truthy. This applies to forced
     and urgent sends too.
4. Build the payload: the shared fields from `formatting.js`, then the
   channel's `payloadFields` merged on top.
5. Call `transport[channel](payload)`.
6. Record the delivery for throttling. This happens only after the transport
   resolves, so a failed delivery does not count toward the limit.

## Design decisions

Channel definitions replace subclasses. Each subclass overrode three or four
template hooks and called `super` at different points: email and SMS ran the
base throttle check first, while Slack and in-app ran their own check first and
could skip the base one. That ordering lived in where each `super` call sat. A
definition states the differences as data (defaults, extra user rules,
exemptions, consent rules) plus one pure function for payload fields. The
pipeline order is written once, in `composeNotifier.js`.

The throttle policy has a fixed order (exemptions, rate limit, consent) instead
of a per-channel rule list. All four channels fit it, and a fixed order stops a
new channel from accidentally putting consent ahead of an exemption. A channel
that needs another order would require changing the policy itself.

Notifiers are closures, and the returned object is frozen. `send` calls the
stage functions it closes over, so reassigning `notifier.deliver` could not
change what `send` does, unlike overriding a method on a class instance.
Freezing makes that visible: the assignment throws in strict-mode code.

Registry values are plain functions rather than arrow functions, so both
`registry.email(options)` and the class-era `new registry.email(options)` return
a notifier.

Some expressions are kept exactly as the classes wrote them because rewrites
that look equivalent are not:

- `recent.length >= maxPerHour` rather than a negated `<`, which disagrees when
  `maxPerHour` is a non-numeric string.
- `options.x || default` fallbacks rather than `??`, so `0` and `''` still fall back.
- In-app expiry multiplies `hours * 60 * 60 * 1000` left to right. A
  precomputed milliseconds-per-hour constant rounds differently for
  fractional hours.
- The clock is read in the same order: rate check, payload `id`,
  `generatedAt`, in-app expiry, delivery record.
- The transport is called as a method, so `this` is the transport object.

## Compatibility with the class-based version

Unchanged: the three exports, send results, payloads (including key order),
throttling, and the errors this library throws for invalid users, messages,
channels and missing transports.

Changed:

- A notifier is a frozen object with `channel`, `send`, `validateUser`,
  `validateMessage`, `shouldThrottle`, `format`, `deliver` and
  `recordDelivery`. Config fields (`transport`, `maxPerHour`, `from`, ...) and
  helper methods (`throttleKey`, `applyTemplate`, `escapeHtml`, `footerFor`,
  `truncate`, `blocksFor`) are no longer members, and `instanceof` checks
  against the removed classes no longer apply.
- `Notifier.js`, `EmailNotifier.js`, `SmsNotifier.js`, `SlackNotifier.js` and
  `InAppNotifier.js` are gone. Import from `index.js`.
- `createNotifier` looks up own registry keys only. Inherited names such as
  `'constructor'` now throw `unknown notification channel`. Before, they
  returned the options object or failed with an unrelated `TypeError`.
- Registry entries are called without `new`, so registering a class no longer works.
- Factory options are read directly. The base class used to receive an object
  spread copy, so inherited properties on the options object were ignored for
  `transport`, `throttleStore`, `now` and `defaultLocale`. They now apply.
- The `templates` and `defaultSender` options were stored but never used.
  They are now ignored.
- Malformed options, such as `null` options or a `now` that is not a
  function, still throw a `TypeError` at the same point. The runtime's message
  names different variables, for example `now is not a function` instead of
  `this.now is not a function`.

## Known limitations

These behaviors are unchanged by the refactor:

- The throttle store keeps every delivery timestamp. Old entries are filtered
  out on read but never deleted, so the default `Map` grows for the life of the
  notifier. Pass a store with its own expiry for long-running processes.
- SMS truncation and segment counts use UTF-16 string length. A cut can split
  an emoji, and segment counts ignore GSM-7/UCS-2 encoding limits.

## Adding a channel

Write a definition in `channels/` with the fields documented on the
`ChannelDefinition` typedef in `composeNotifier.js`, then register it in
`index.js` with `notifierFactory`.

