const { composeNotifier } = require('./composeNotifier');
const email = require('./channels/email');
const sms = require('./channels/sms');
const slack = require('./channels/slack');
const inApp = require('./channels/inapp');

// Returns a plain function, not an arrow, so `new registry.email(options)`
// (valid when registry values were classes) still returns the notifier.
function notifierFactory(definition) {
  return function createChannelNotifier(options = {}) {
    return composeNotifier(definition, options);
  };
}

/** Channel id to notifier factory. `createNotifier` looks channels up here. */
const registry = {
  email: notifierFactory(email),
  sms: notifierFactory(sms),
  slack: notifierFactory(slack),
  inapp: notifierFactory(inApp)
};

/**
 * Creates a notifier for one registered channel.
 * @param {string} channel  A key of `registry`.
 * @param {object} [options]  Shared options (transport, throttleStore, now,
 *   defaultLocale, maxPerHour) plus the channel's own settings.
 * @throws {TypeError} When `channel` is not a registered channel.
 */
function createNotifier(channel, options = {}) {
  // Own keys only: inherited names such as "constructor" are not channels.
  const factory = Object.hasOwn(registry, channel) ? registry[channel] : undefined;
  if (typeof factory !== 'function') {
    throw new TypeError(`unknown notification channel: ${channel}`);
  }
  return factory(options);
}

/** Creates one notifier per registered channel, keyed by channel id, from the same options. */
function createAllNotifiers(options = {}) {
  return Object.keys(registry).reduce((all, channel) => {
    all[channel] = createNotifier(channel, options);
    return all;
  }, {});
}

module.exports = {
  createNotifier,
  createAllNotifiers,
  registry
};
/**
 * @typedef {object} ValidationRule
 * @property {(value: any) => boolean} check  Returns true when the value is acceptable.
 * @property {string} error  Message of the TypeError thrown when `check` fails.
 */

/**
 * Recipient rules every channel applies before its own `userRules`.
 * @type {ValidationRule[]}
 */
const USER_RULES = [
  { check: user => Boolean(user) && typeof user === 'object', error: 'user is required' },
  { check: user => Boolean(user.id), error: 'user.id is required' }
];

/** @type {ValidationRule[]} */
const MESSAGE_RULES = [
  { check: message => Boolean(message) && typeof message === 'object', error: 'message is required' },
  {
    check: message => Boolean(message.title && message.body),
    error: 'message.title and message.body are required'
  }
];

/**
 * Throws a TypeError for the first rule `value` fails. Rules run in order and
 * stop at the first failure, so a rule may rely on the ones before it.
 * @param {ValidationRule[]} rules
 * @param {unknown} value
 */
function assertRules(rules, value) {
  const failed = rules.find(rule => !rule.check(value));
  if (failed) {
    throw new TypeError(failed.error);
  }
}

module.exports = {
  USER_RULES,
  MESSAGE_RULES,
  assertRules
};
const { requireMarketingOptIn } = require('../throttling');

const EMAIL_PREVIEW_LENGTH = 90;

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function footerFor(user, message, unsubscribeBaseUrl) {
  if (message.category === 'transactional' || message.category === 'security') {
    return `Sent to ${user.email} because of recent account activity.`;
  }
  const url = `${unsubscribeBaseUrl}?user=${encodeURIComponent(user.id)}`;
  return `You can unsubscribe at ${url}.`;
}

/** @type {import('../composeNotifier').ChannelDefinition} */
module.exports = {
  name: 'email',
  transportLabel: 'email',
  defaults: {
    maxPerHour: 8,
    from: 'noreply@example.com',
    replyTo: 'support@example.com',
    unsubscribeBaseUrl: 'https://example.com/unsubscribe'
  },
  userRules: [
    {
      check: user => Boolean(user.email) && user.email.includes('@'),
      error: 'user.email is required for email notifications'
    }
  ],
  throttleExemptions: [],
  consentRules: [requireMarketingOptIn('emailOptIn', 'email')],
  payloadFields(base, { user, message, settings }) {
    const subjectPrefix = message.category === 'security' ? '[Action Required] ' : '';
    const footer = footerFor(user, message, settings.unsubscribeBaseUrl);

    return {
      to: user.email,
      from: settings.from,
      replyTo: settings.replyTo,
      subject: `${subjectPrefix}${base.title}`,
      text: `${base.body}\n\n${footer}`,
      html: `<h1>${escapeHtml(base.title)}</h1><p>${escapeHtml(base.body)}</p><footer>${escapeHtml(footer)}</footer>`,
