const THROTTLE_WINDOW_MS = 60 * 60 * 1000;

/**
 * @typedef {object} ThrottleDecision
 * @property {boolean} throttled
 * @property {string} [reason]
 * @property {string|null} [retryAt]  ISO timestamp, or null when waiting will not help.
 */

/**
 * @typedef {object} ConsentRule
 * @property {(user: object, message: object) => boolean} denies
 * @property {string} reason
 */

/**
 * Hourly send limit per channel, user id and message category. Delivery
 * timestamps live in `store` (anything with Map-style get/set), so notifiers
 * given the same store share history.
 */
function createRateLimiter({ channel, store, now, maxPerHour }) {
  function keyFor(user, message) {
    return `${channel}:${user.id}:${message.category || 'general'}`;
  }

  return {
    /** @returns {ThrottleDecision|null} null when the limit does not block this send. */
    check(user, message, options) {
      if (options.force || message.priority === 'urgent') {
        return null;
      }

      const key = keyFor(user, message);
      const nowMs = now().getTime();
      const recent = (store.get(key) || []).filter(ts => nowMs - ts < THROTTLE_WINDOW_MS);

      if (recent.length >= maxPerHour) {
        return {
          throttled: true,
          reason: `${channel} hourly limit reached`,
          retryAt: new Date(recent[0] + THROTTLE_WINDOW_MS).toISOString()
        };
      }

      return null;
    },

    record(user, message) {
      const key = keyFor(user, message);
      const records = store.get(key) || [];
      records.push(now().getTime());
      store.set(key, records);
    }
  };
}

/**
 * Consent rule that blocks marketing messages unless `user[optInField]` is truthy.
 * @param {string} optInField
 * @param {string} audience  Channel wording used in the throttle reason.
 * @returns {ConsentRule}
 */
function requireMarketingOptIn(optInField, audience) {
  return {
    denies: (user, message) => message.category === 'marketing' && !user[optInField],
    reason: `user has not opted into marketing ${audience}`
  };
}

/**
 * Throttle policy shared by every channel. Order: a matching exemption allows
 * the send outright; then the rate limit; then consent rules. `force` and
 * urgent priority only skip the rate limit, so consent still applies to them.
 * @returns {(user: object, message: object, options?: object) => ThrottleDecision}
 */
function createThrottlePolicy({ exemptions, rateLimiter, consentRules }) {
  return function shouldThrottle(user, message, options = {}) {
    if (exemptions.some(isExempt => isExempt(user, message, options))) {
      return { throttled: false };
    }

    const limited = rateLimiter.check(user, message, options);
    if (limited) {
      return limited;
    }

    const denied = consentRules.find(rule => rule.denies(user, message));
    if (denied) {
      return { throttled: true, reason: denied.reason, retryAt: null };
    }

    return { throttled: false };
  };
}

module.exports = {
  createRateLimiter,
  createThrottlePolicy,
  requireMarketingOptIn
};
